import { describe, expect, it } from "vitest";
import { roundCents } from "../src/billing/round";

describe("roundCents", () => {
  it("rounds half-cent ties to the even cent so ties don't bias invoices upward", () => {
    expect(roundCents(0.5)).toBe(0);
    expect(roundCents(1.5)).toBe(2);
    expect(roundCents(2.5)).toBe(2);
    expect(roundCents(101.5)).toBe(102);
  });

  it("rounds non-ties to the nearest cent", () => {
    expect(roundCents(10.49)).toBe(10);
    expect(roundCents(10.51)).toBe(11);
    expect(roundCents(7)).toBe(7);
  });

  it("applies the same tie rule to refunds and credits", () => {
    expect(roundCents(-2.5)).toBe(-2);
    expect(roundCents(-3.5)).toBe(-4);
    expect(roundCents(-1.4)).toBe(-1);
    expect(roundCents(-1.6)).toBe(-2);
  });
});

